999: 		return false, err
1000: 	}
1001: 	profile, err := s.autoStartReviewProfile(ctx.Context, project, home)
1002: 	if err == nil {
1003: 		err = s.startReviewRound(ctx, db, home, project, change, profile, "")
1004: 	}
1005: 	if failure, unavailable := autoStartReviewerUnavailable(err); unavailable {
1006: 		if noticeErr := recordAutoStartReviewerReadiness(ctx.Context, db, project, change, targets, failure); noticeErr != nil {
